#include <vector>

class Solution {
public:
    /**
     * 二分搜尋
     * 時間複雜度: O(log n)
     * 空間複雜度: O(1)
     */
    int search(std::vector<int>& nums, int target) {
        int left = 0, right = nums.size() - 1;

        while (left <= right) {
            // 計算中間位置（避免溢位）
            int mid = left + (right - left) / 2;

            // 找到目標值
            if (nums[mid] == target) {
                return mid;
            }

            // 目標在右半部分
            else if (nums[mid] < target) {
                left = mid + 1;
            }

            // 目標在左半部分
            else {
                right = mid - 1;
            }
        }

        // 未找到目標值
        return -1;
    }
};

